import { Table, StringColumn, ReferenceColumn } from '../../db'

export const sys_scope_privilege = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'source_scope',
    extends: 'sys_metadata',
    label: 'Cross scope privilege',
    name: 'sys_scope_privilege',
    schema: {
        target_name: StringColumn({
            label: 'Target Name',
            mandatory: true,
            maxLength: 255,
        }),

        status: StringColumn({
            default: 'requested',
            choices: {
                requested: {
                    label: 'Requested',
                    sequence: 1,
                },
                denied: {
                    label: 'Denied',
                    sequence: 2,
                },
                allowed: {
                    label: 'Allowed',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Status',
        }),
        target_scope: ReferenceColumn({
            label: 'Target Scope',
            mandatory: true,
            referenceTable: 'sys_scope',
            referenceQual: 'private=false^ORprivateISEMPTY^EQ',
            useReferenceQualifier: 'simple',
        }),
        operation: StringColumn({
            default: 'read',
            choices: {
                read: {
                    label: 'Read',
                    sequence: 1,
                    dependentValue: 'sys_db_object',
                },
                write: {
                    label: 'Write',
                    sequence: 2,
                    dependentValue: 'sys_db_object',
                },
                create: {
                    label: 'Create',
                    sequence: 3,
                    dependentValue: 'sys_db_object',
                },
                delete: {
                    label: 'Delete',
                    sequence: 4,
                    dependentValue: 'sys_db_object',
                },
                execute: [
                    {
                        label: 'Execute API',
                        sequence: 6,
                        dependentValue: 'sys_script_include',
                    },
                    {
                        label: 'Execute API',
                        sequence: 7,
                        dependentValue: 'scriptable',
                    },
                ],
            },
            dropdown: 'dropdown_without_none',
            dependent: 'target_type',
            label: 'Operation',
            mandatory: true,
        }),
        target_type: StringColumn({
            default: 'sys_db_object',
            choices: {
                sys_db_object: {
                    label: 'Table',
                    sequence: 1,
                },
                sys_script_include: {
                    label: 'Script Include',
                    sequence: 2,
                },
                scriptable: {
                    label: 'Scriptable',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Target Type',
            mandatory: true,
        }),
        source_scope: ReferenceColumn({
            default: 'javascript:gs.getCurrentApplicationId();',
            label: 'Source Scope',
            mandatory: true,
            readOnly: true,
            readOnlyOption: 'client_script_modifiable',
            referenceTable: 'sys_scope',
            referenceQual: 'restrict_runtime_access=true^sys_id=javascript:gs.getCurrentApplicationId()^EQ',
            useReferenceQualifier: 'simple',
        }),
    },
})
